function KNEE(w, n, tau):
    require n >= 1 and 0 < tau <= 1
    M[0] <- 0
    for i <- 0 to n-1:
        M[i+1] <- M[i] + w(i)
    threshold <- tau * M[n]
    for k <- 0 to n:
        if M[k] >= threshold:
            return k
    return n                      # unreachable when tau <= 1

function DILATION_WINDOW(K, c):
    return (c*(K-1), c*K]         # half-open, contains exactly c integers

function COMPATIBLE_DEPTHS(K, M, cmax):
    D <- empty list
    for c <- 1 to cmax:
        if c*(K-1) < M and M <= c*K:
            append c to D
    return D                      # empty  =>  M is not any block dilation of K

function AUDIT_ROW(base, row):
    defect <- row.short * base.long - row.long * base.short
    if defect = 0:
        factor <- row.short / base.short          # exact rational; unique
    else:
        factor <- NONE
    predicted <- (row.short / base.short) * base.long
    depths <- COMPATIBLE_DEPTHS(base.short, row.short, cmax)
    return (defect, factor, predicted, predicted - row.long, depths)

function AUDIT_TABLE(base, rows):
    results <- [AUDIT_ROW(base, r) for r in rows]
    verdict <- all(r.defect = 0 for r in results)
    quantised <- all(4 divides r.short and 4 divides r.long for r in rows)
    return (results, verdict, quantised, set of increments)

function CEIL_DIV(a, b):  return -((-a) div b)

function MERGED_KNEE(w, q, n, tau):
    K <- KNEE(w, q*n, tau)
    return CEIL_DIV(K, q)                       # exact, not a bound

function RATIONAL_WINDOW(w, p, q, n, tau):
    c <- CEIL_DIV(KNEE(w, q*n, tau), q)
    return (p*(c-1), p*c]                       # window for the p/q rescaling

function MIN_DEPTH_FOR_FLAT_COLUMN(short, long):
    for q <- 1 to qmax:
        if CEIL_DIV(short, q) = CEIL_DIV(long, q):
            return q                            # ceiling absorbs the increment
    fail

